using System.IO;
using NUnit.Framework;

namespace Game.Sim.Tests;

// The balance json actually shipped in Assets/Data (generated by Tools/csv2json.py).
internal static class RepoData
{
    private static GameData? _cached;

    // GameData is immutable, so one instance serves every test.
    public static GameData Get() => _cached ??= Load();

    public static GameData Load()
    {
        string dir = Path.Combine(RepoRoot(), "Assets", "Data");
        string Read(string name) => File.ReadAllText(Path.Combine(dir, name));
        return GameData.Parse(new GameDataSources
        {
            Units = Read("units.json"),
            Buildings = Read("buildings.json"),
            CreepCamps = Read("creep_camps.json"),
            Rules = Read("rules.json"),
            Legion = Read("legion.json"),
            Waves = Read("waves.json"),
            Factions = Read("factions.json"),
            Abilities = Read("abilities.json"),
            HeroLevels = Read("hero_levels.json"),
        });
    }

    public static string RepoRoot()
    {
        var dir = new DirectoryInfo(TestContext.CurrentContext.TestDirectory);
        while (dir != null && !File.Exists(Path.Combine(dir.FullName, "PLAN.md")))
            dir = dir.Parent;
        return dir?.FullName ?? throw new DirectoryNotFoundException("Repository root (PLAN.md) not found.");
    }
}
